/* ============================================
   RedRoom Fitness — Global Styles
   ============================================ */

:root {
  --red: #FF0000;
  --red-dark: #cc0000;
  --bg: #141414;
  --bg-light: #1a1a1a;
  --bg-lighter: #222;
  --text: #FFFFFF;
  --text-muted: #b3b3b3;
  --text-dim: #888;
  --border: #333;
  --font-headline: 'Oswald', 'Bebas Neue', 'Impact', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --radius: 4px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--text);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--red);
}

img {
  max-width: 100%;
  display: block;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
  font-weight: 700;
}

h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); }
h2 { font-size: clamp(1.8rem, 4vw, 3rem); }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.6rem); }

p {
  color: var(--text-muted);
  font-size: 1rem;
  max-width: 65ch;
}

.section-label {
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  color: var(--red);
  margin-bottom: 0.75rem;
}

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

section {
  padding: 5rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-header h2 {
  margin-bottom: 1rem;
}

.section-header p {
  margin: 0 auto;
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-block;
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  padding: 1rem 2.5rem;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.25s ease;
  border: 2px solid transparent;
  text-align: center;
}

.btn-primary {
  background-color: var(--red);
  color: var(--text);
  border-color: var(--red);
}

.btn-primary:hover {
  background-color: var(--red-dark);
  border-color: var(--red-dark);
  color: var(--text);
}

.btn-outline {
  background-color: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background-color: var(--text);
  color: var(--bg);
}

.btn-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* ============================================
   Top Bar
   ============================================ */

.top-bar {
  background-color: var(--red);
  text-align: center;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
}

.top-bar a {
  color: var(--text);
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: 0.5rem;
}

.top-bar a:hover {
  opacity: 0.9;
}

/* ============================================
   Navigation
   ============================================ */

.site-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background-color: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-headline);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text);
}

.logo span {
  color: var(--red);
}

.logo:hover {
  color: var(--text);
}

.nav-links {
  display: flex;
  gap: 1.75rem;
  list-style: none;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  transition: color 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-utilities {
  display: flex;
  gap: 1.25rem;
  align-items: center;
}

.nav-utilities a {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.nav-utilities .btn-sm {
  padding: 0.5rem 1.2rem;
  font-size: 0.75rem;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  font-size: 1.5rem;
  cursor: pointer;
}

/* ============================================
   Hero
   ============================================ */

.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: 4rem 1.5rem;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #141414 60%, #0a0a0a 100%);
  z-index: 0;
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 30%, rgba(255,0,0,0.12) 0%, transparent 60%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 900px;
}

.hero h1 {
  margin-bottom: 1.25rem;
  text-shadow: 0 2px 20px rgba(0,0,0,0.5);
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-group {
  margin-top: 0.5rem;
}

/* ============================================
   Cards & Grids
   ============================================ */

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.card {
  background-color: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  transition: transform 0.2s, border-color 0.2s;
}

.card:hover {
  transform: translateY(-4px);
  border-color: var(--red);
}

.card h3 {
  margin-bottom: 0.75rem;
  color: var(--text);
}

.card p {
  font-size: 0.95rem;
}

/* ============================================
   Two Ways / Split
   ============================================ */

.split-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.split-card {
  background-color: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 3rem 2.5rem;
  position: relative;
  overflow: hidden;
}

.split-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
}

.split-card h3 {
  margin-bottom: 1rem;
}

.split-card p {
  margin-bottom: 1.5rem;
}

/* ============================================
   Studio Experience
   ============================================ */

.studio-section {
  background-color: var(--bg-light);
  text-align: center;
}

.studio-section p {
  margin: 0 auto 2rem;
}

/* ============================================
   CTA Banner
   ============================================ */

.cta-banner {
  background: linear-gradient(90deg, var(--red-dark), var(--red));
  text-align: center;
  padding: 4rem 1.5rem;
}

.cta-banner h2 {
  margin-bottom: 1.25rem;
  color: var(--text);
}

.cta-banner .btn-outline {
  border-color: var(--text);
  color: var(--text);
}

.cta-banner .btn-outline:hover {
  background-color: var(--text);
  color: var(--red);
}

/* ============================================
   Carousel
   ============================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  background-color: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.7;
}

.carousel-slide .slide-caption {
  position: absolute;
  bottom: 2rem;
  left: 2rem;
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 1.5rem;
  background: rgba(0,0,0,0.6);
  padding: 0.5rem 1rem;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,0.5);
  border: 1px solid var(--border);
  color: var(--text);
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1.25rem;
  transition: background 0.2s;
  z-index: 2;
}

.carousel-btn:hover {
  background: rgba(255,0,0,0.7);
}

.carousel-btn.prev { left: 1rem; }
.carousel-btn.next { right: 1rem; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: background 0.2s;
}

.carousel-dot.active {
  background: var(--red);
}

/* ============================================
   Newsletter
   ============================================ */

.newsletter {
  text-align: center;
}

.newsletter p {
  margin: 0 auto 1.5rem;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  min-width: 220px;
  padding: 0.9rem 1rem;
  background-color: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.2s;
}

.newsletter-form input:focus {
  border-color: var(--red);
}

.newsletter-form input::placeholder {
  color: var(--text-dim);
}

.newsletter-msg {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5em;
}

.newsletter-msg.success {
  color: #4ade80;
}

.newsletter-msg.error {
  color: var(--red);
}

/* ============================================
   Footer
   ============================================ */

.site-footer {
  background-color: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 0.9rem;
  margin-bottom: 1.25rem;
  color: var(--text);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.6rem;
}

.footer-col a {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.footer-col a:hover {
  color: var(--red);
}

.country-select {
  position: relative;
}

.country-select-btn {
  background: var(--bg-light);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  list-style: none;
  min-width: 160px;
  display: none;
  margin-bottom: 0.25rem;
  overflow: hidden;
}

.country-dropdown.open {
  display: block;
}

.country-dropdown li {
  margin: 0;
}

.country-dropdown a {
  display: block;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
}

.country-dropdown a:hover {
  background: var(--bg-lighter);
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  font-size: 0.8rem;
  color: var(--text-dim);
}

/* ============================================
   Workout Page — Toggle
   ============================================ */

.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 2rem;
}

.toggle-btn {
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 1rem;
  letter-spacing: 0.06em;
  padding: 0.85rem 2.5rem;
  background: var(--bg-light);
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.25s;
}

.toggle-btn:first-child {
  border-radius: var(--radius) 0 0 var(--radius);
}

.toggle-btn:last-child {
  border-radius: 0 var(--radius) var(--radius) 0;
}

.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.toggle-btn:hover:not(.active) {
  color: var(--text);
}

.toggle-panel {
  display: none;
  animation: fadeIn 0.35s ease;
}

.toggle-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Workout Page — Schedule Table
   ============================================ */

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1rem;
}

.schedule-table th,
.schedule-table td {
  padding: 1.1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

.schedule-table th {
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  color: var(--text-dim);
  background: var(--bg-light);
}

.schedule-table td {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.schedule-table td:first-child {
  color: var(--text);
  font-weight: 600;
}

.schedule-table tr:hover td {
  background: rgba(255,0,0,0.04);
}

/* ============================================
   Instructors — Filter & Grid
   ============================================ */

.filter-bar {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
}

.filter-pill {
  font-family: var(--font-headline);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.05em;
  padding: 0.6rem 1.4rem;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  border-radius: 100px;
  transition: all 0.2s;
}

.filter-pill:hover,
.filter-pill.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.instructor-card {
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
}

.instructor-card:hover {
  transform: translateY(-4px);
  border-color: var(--red);
}

.instructor-photo {
  width: 100%;
  height: 280px;
  background: linear-gradient(135deg, #2a0a0a, #1a1a1a);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red);
  text-transform: uppercase;
}

.instructor-info {
  padding: 1.25rem;
}

.instructor-info h4 {
  font-size: 1.1rem;
  margin-bottom: 0.25rem;
}

.instructor-info p {
  font-size: 0.85rem;
  color: var(--text-dim);
  margin-bottom: 1rem;
}

.instructor-info a {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red);
}

.instructor-info a:hover {
  color: var(--text);
}

/* ============================================
   FAQ Accordion
   ============================================ */

.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  background: none;
  border: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 600;
  text-align: left;
  padding: 1.5rem 0;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s;
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-icon {
  font-size: 1.25rem;
  transition: transform 0.3s ease;
  color: var(--red);
}

.accordion-item.open .accordion-icon {
  transform: rotate(45deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.accordion-item.open .accordion-body {
  max-height: 300px;
  padding-bottom: 1.5rem;
}

.accordion-body p {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* ============================================
   Digital Platform — Features
   ============================================ */

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2.5rem 2rem;
  transition: border-color 0.2s;
}

.feature-card:hover {
  border-color: var(--red);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(255,0,0,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.25rem;
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.2rem;
}

.feature-card p {
  font-size: 0.95rem;
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 900px) {
  .split-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .nav-links {
    display: none;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: var(--bg);
    flex-direction: column;
    padding: 1.5rem;
    border-bottom: 1px solid var(--border);
    gap: 1rem;
  }

  .nav-links.open {
    display: flex;
  }

  .nav-toggle {
    display: block;
  }

  .nav-utilities {
    display: none;
  }

  .carousel-slide {
    height: 350px;
  }
}

@media (max-width: 600px) {
  section {
    padding: 3rem 0;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .hero {
    min-height: 60vh;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 0.85rem 1rem;
  }
}

/* ============================================
   RedRoom Fitness — Main JavaScript
   ============================================ */

document.addEventListener('DOMContentLoaded', () => {
  initMobileNav();
  initCarousel();
  initWorkoutToggle();
  initInstructorFilter();
  initFAQAccordion();
  initNewsletterForm();
  initCountrySelector();
});

/* Mobile Nav */
function initMobileNav() {
  const toggle = document.querySelector('.nav-toggle');
  const links = document.querySelector('.nav-links');
  if (!toggle || !links) return;

  toggle.addEventListener('click', () => {
    links.classList.toggle('open');
    toggle.setAttribute('aria-expanded', links.classList.contains('open'));
  });
}

/* Carousel */
function initCarousel() {
  const track = document.querySelector('.carousel-track');
  if (!track) return;

  const slides = track.querySelectorAll('.carousel-slide');
  const prevBtn = document.querySelector('.carousel-btn.prev');
  const nextBtn = document.querySelector('.carousel-btn.next');
  const dotsContainer = document.querySelector('.carousel-dots');
  let current = 0;
  let startX = 0;

  if (slides.length === 0) return;

  // Create dots
  if (dotsContainer) {
    slides.forEach((_, i) => {
      const dot = document.createElement('button');
      dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
      dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
      dot.addEventListener('click', () => goTo(i));
      dotsContainer.appendChild(dot);
    });
  }

  function goTo(index) {
    if (index < 0) index = slides.length - 1;
    if (index >= slides.length) index = 0;
    current = index;
    track.style.transform = `translateX(-${current * 100}%)`;

    document.querySelectorAll('.carousel-dot').forEach((dot, i) => {
      dot.classList.toggle('active', i === current);
    });
  }

  if (prevBtn) prevBtn.addEventListener('click', () => goTo(current - 1));
  if (nextBtn) nextBtn.addEventListener('click', () => goTo(current + 1));

  // Swipe support
  const carousel = track.closest('.carousel');
  if (carousel) {
    carousel.addEventListener('touchstart', e => {
      startX = e.touches[0].clientX;
    }, { passive: true });

    carousel.addEventListener('touchend', e => {
      const diff = startX - e.changedTouches[0].clientX;
      if (Math.abs(diff) > 50) {
        goTo(current + (diff > 0 ? 1 : -1));
      }
    }, { passive: true });
  }
}

/* Workout Toggle */
function initWorkoutToggle() {
  const btns = document.querySelectorAll('.toggle-btn');
  const panels = document.querySelectorAll('.toggle-panel');
  if (btns.length === 0) return;

  btns.forEach(btn => {
    btn.addEventListener('click', () => {
      const target = btn.dataset.target;

      btns.forEach(b => b.classList.toggle('active', b.dataset.target === target));
      panels.forEach(p => p.classList.toggle('active', p.id === target));
    });
  });
}

/* Instructor Filter */
function initInstructorFilter() {
  const pills = document.querySelectorAll('.filter-pill');
  const cards = document.querySelectorAll('.instructor-card');
  if (pills.length === 0) return;

  pills.forEach(pill => {
    pill.addEventListener('click', () => {
      const location = pill.dataset.location;

      pills.forEach(p => p.classList.toggle('active', p === pill));

      cards.forEach(card => {
        const cardLoc = card.dataset.location;
        const show = location === 'all' || cardLoc === location;
        card.style.display = show ? '' : 'none';
        if (show) {
          card.style.animation = 'fadeIn 0.35s ease';
        }
      });
    });
  });
}

/* FAQ Accordion */
function initFAQAccordion() {
  const items = document.querySelectorAll('.accordion-item');
  if (items.length === 0) return;

  items.forEach(item => {
    const header = item.querySelector('.accordion-header');
    if (!header) return;

    header.addEventListener('click', () => {
      const isOpen = item.classList.contains('open');

      // Close all
      items.forEach(i => i.classList.remove('open'));

      // Open clicked if it was closed
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });
}

/* Newsletter Form */
function initNewsletterForm() {
  const form = document.querySelector('.newsletter-form');
  if (!form) return;

  form.addEventListener('submit', e => {
    e.preventDefault();
    const input = form.querySelector('input[type="email"]');
    const msg = form.parentElement.querySelector('.newsletter-msg');
    const email = input.value.trim();

    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

    if (!valid) {
      msg.textContent = 'Please enter a valid email address.';
      msg.className = 'newsletter-msg error';
      return;
    }

    msg.textContent = 'You\'re in! Check your inbox for confirmation.';
    msg.className = 'newsletter-msg success';
    input.value = '';
  });
}

/* Country Selector */
function initCountrySelector() {
  const btn = document.querySelector('.country-select-btn');
  const dropdown = document.querySelector('.country-dropdown');
  if (!btn || !dropdown) return;

  btn.addEventListener('click', e => {
    e.stopPropagation();
    dropdown.classList.toggle('open');
  });

  document.addEventListener('click', () => {
    dropdown.classList.remove('open');
  });

  dropdown.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', e => {
      e.preventDefault();
      const country = link.textContent;
      btn.querySelector('span').textContent = country;
      dropdown.classList.remove('open');
    });
  });
}
